import React from 'react'

const Services = () => {
  return (
    <div className="service-page">
      {servicesData.map((section, index) => (
        <div className="service-section" key={index}>
          <img src="" alt="Audio Wave" className="audio-wave" />
          <h2 className="section-title">{section.title}</h2>

          <div className="service-items">
            {section.items.map((item, itemIndex) => (
              <div className="service-item" key={itemIndex}>
                <h3 className="service-name">{item.name}</h3>
                <p className="service-price">{item.price}</p>
                <p className="service-description">{item.description}</p>
              </div>
            ))}
          </div>
        </div>
      ))}

      <img src="" alt="Logo" className="bottom-logo" />
      <button className="contact-button">Связаться с нами!</button>
    </div>
  );
}

export default Services
